32: /**
33:  * Creates a new session in database and returns token.
34:  */
35: export async function createSession(userId: string, userAgent?: string, ipAddress?: string): Promise<{ token: string; expiresAt: Date }> {
36:   const token = createToken();
37:   const tokenHash = hashToken(token);
38:   const expiresAt = new Date(Date.now() + SESSION_EXPIRY_DAYS * 24 * 60 * 60 * 1000);
39: 
40:   try {
41:     if (db?.session?.create) {
42:       await db.session.create({
43:         data: {
44:           userId,
45:           tokenHash,
46:           userAgent,
47:           ipAddress,
48:           expiresAt
49:         }
50:       });
51:     }
52:   } catch (err) {
53:     console.warn('[NagrikOne Session] DB session creation error:', err);
54:   }
55: 
56:   return { token, expiresAt };
57: }
