97: export async function getCurrentUser(): Promise<AuthSession | null> {
98:   try {
99:     const cookieStore = await cookies();
100:     const token = cookieStore.get(SESSION_COOKIE_NAME)?.value;
101:     if (!token) return null;
102:     return await getSessionFromToken(token);
